{
  "findings": [
    {
      "check_id": "CKV_AZURE_112",
      "title": "Ensure that key vault key is backed by HSM",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The key vault key is not backed by a Hardware Security Module (HSM), which may reduce the security posture of the key."
    }
  ],
  "patched_code": "resource "azurerm_key_vault_key" "generated" {
  name         = "terragoat-generated-certificate-${var.environment}"
  key_vault_id = azurerm_key_vault.example.id
  key_type     = "RSA-HSM"
  key_size     = 2048
  key_opts = [
    "decrypt",
    "encrypt",
    "sign",
    "unwrapKey",
    "verify",
    "wrapKey",
  ]
}",
  "fix_summary": "Changed the key_type from 'RSA' to 'RSA-HSM' to ensure the key vault key is backed by HSM."
}
